--faint:#5f7568;--line:#1f4536;--line2:#163329;--gold:#cba95f;--green:#46a878;
--warn:#d9a441;--no:#e0836a;
--sh-sm:0 1px 2px rgba(0,0,0,.3);--sh:0 2px 4px rgba(0,0,0,.3),0 18px 40px rgba(0,0,0,.5)}
*{box-sizing:border-box}
body{margin:0;color:var(--ink);font-family:'Jost',system-ui,sans-serif;font-weight:300;
line-height:1.6;-webkit-font-smoothing:antialiased;
background:var(--bg);
background-image:radial-gradient(1200px 680px at 50% -12%,#123227 0%,rgba(18,50,39,0) 60%),
radial-gradient(900px 500px at 88% 8%,rgba(203,169,95,.05) 0%,rgba(203,169,95,0) 55%);
background-attachment:fixed}
.wrap{max-width:1180px;margin:0 auto;padding:1.4rem 1.25rem 5rem}
a{color:var(--gold)}
h1,.brand,.jc .cc,.tile .v,h2.sec,.med .big{font-variant-numeric:tabular-nums}
.top{display:flex;align-items:center;gap:.75rem;padding:.8rem 0 1.2rem;
border-bottom:1px solid var(--line);flex-wrap:wrap}
.mark{width:38px;height:38px;border-radius:50%;border:1px solid rgba(203,169,95,.4);
background:#1a3224;display:grid;place-items:center;color:var(--gold);
font-family:'Cormorant Garamond',Georgia,serif;font-size:1.3rem;
box-shadow:inset 0 1px 0 rgba(203,169,95,.25)}
.brand{font-family:'Cormorant Garamond',Georgia,serif;font-size:1.4rem;font-weight:600;
letter-spacing:.01em}
.brand small{display:block;font-family:'Jost',sans-serif;font-size:.6rem;font-weight:500;
letter-spacing:.24em;text-transform:uppercase;color:var(--faint);margin-top:-.15rem}
.topnav{margin-left:auto;display:flex;gap:.45rem;flex-wrap:wrap}
.topnav a{font-size:.8rem;text-decoration:none;color:var(--soft);border:1px solid var(--line);
padding:.3rem .75rem;border-radius:9px}
.topnav a:hover{border-color:var(--gold);color:var(--gold)}
.hero{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:2.4rem;align-items:center;
margin:2.4rem 0 2rem}
@media(max-width:820px){.hero{grid-template-columns:1fr;gap:1.6rem}}
.eyebrow{font-size:.68rem;letter-spacing:.28em;text-transform:uppercase;color:var(--gold);
font-weight:600;margin:0 0 .55rem}
h1{font-family:'Cormorant Garamond',Georgia,serif;font-weight:600;
font-size:clamp(2.3rem,4.6vw,3.4rem);line-height:1.02;margin:0}
h1 em{font-style:italic;color:var(--gold)}
h1::after{content:"";display:block;width:60px;height:2px;margin:.7rem 0 0;border-radius:2px;
